package com.minewaku.chatter.identityaccess.user.internal.application;
import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.minewaku.chatter.identityaccess.user.*; import com.minewaku.chatter.identityaccess.user.internal.model.*; import com.minewaku.chatter.identityaccess.user.internal.port.*;
@Service public class RegisterUserService implements RegisterUserUseCase { private final UserAccountRepository repo; private final UserIdGenerator ids; private final PasswordHasher passwords; public RegisterUserService(UserAccountRepository r,UserIdGenerator i,PasswordHasher p){repo=r;ids=i;passwords=p;} @Transactional public Result handle(Command c){Email e=new Email(c.email());Username u=new Username(c.username());Birthday b=new Birthday(c.birthday());PlainPassword p=new PlainPassword(c.password());if(repo.findByEmail(e).isPresent())return new AccountAlreadyExists();try{UserAccount a=UserAccount.register(ids.nextId(),e,u,b,passwords.hash(p));repo.save(a);return new Registered(a.id().value());}catch(DataIntegrityViolationException ex){return new AccountAlreadyExists();}} }